nginx_config:
daemon off;
master_process on;
worker_processes 1;
pid /tmp/aegisx-bench-gtdbd1p4/nginx.pid;
error_log /tmp/aegisx-bench-gtdbd1p4/nginx-error.log crit;
events { worker_connections 16384; multi_accept on; }
http {
    access_log off;
    client_body_temp_path /tmp/aegisx-bench-gtdbd1p4/body;
    proxy_temp_path /tmp/aegisx-bench-gtdbd1p4/proxy;
    keepalive_timeout 60s;
    keepalive_requests 100000;

    upstream origin { server 10.42.1.40:3900; keepalive 256; }
    server {
        listen 10.42.1.113:41749 reuseport;
        location / {
            proxy_http_version 1.1;
            proxy_set_header Connection "";
            proxy_set_header Host 10.42.1.40:3900;
            proxy_request_buffering off;
            proxy_buffering off;
            proxy_pass http://origin;
        }
    }
}
